// Generates test/coverage_all_imports_test.dart, a throwaway test that imports
// every library under lib/.
//
// `flutter test --coverage` only reports files that some test loads, so a file
// with no tests at all would be missing from lcov.info instead of counting as
// 0%. Importing everything makes the coverage total honest.
//
// The generated file is gitignored. tool/coverage.sh creates it before the test
// run and deletes it afterwards.
//
// Usage (from frontend/): dart run tool/coverage_all_imports.dart

import 'dart:io';

const _output = 'test/coverage_all_imports_test.dart';

bool _isGenerated(String path) =>
    path.endsWith('.g.dart') || path.endsWith('.freezed.dart');

bool _isPartFile(File file) =>
    file.readAsLinesSync().any((line) => line.trimLeft().startsWith('part of'));

void main() {
  final libDir = Directory('lib');
  if (!libDir.existsSync()) {
    stderr.writeln('Run this from the frontend/ package root.');
    exit(2);
  }

  final imports =
      libDir
          .listSync(recursive: true)
          .whereType<File>()
          .where((f) => f.path.endsWith('.dart'))
          .where((f) => !_isGenerated(f.path))
          .where((f) => !_isPartFile(f))
          .map((f) => f.path.replaceAll(r'\', '/').substring('lib/'.length))
          .toList()
        ..sort();

  final buffer = StringBuffer()
    ..writeln('// GENERATED by tool/coverage_all_imports.dart. Do not commit.')
    ..writeln('// ignore_for_file: unused_import, directives_ordering')
    ..writeln();
  for (final path in imports) {
    buffer.writeln("import 'package:frontend/$path';");
  }
  buffer
    ..writeln()
    ..writeln('void main() {}');

  File(_output).writeAsStringSync(buffer.toString());
  stdout.writeln('Wrote $_output (${imports.length} libraries).');
}
